CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, description TEXT NOT NULL, image VARCHAR(250) NOT NULL DEFAULT '', sort_order INT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS services (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NOT NULL, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, includes TEXT NOT NULL, image VARCHAR(250) NOT NULL DEFAULT '', price DECIMAL(10,2) NULL, featured TINYINT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS packages (id INT AUTO_INCREMENT PRIMARY KEY, image VARCHAR(250) NOT NULL DEFAULT '', name VARCHAR(150) NOT NULL, description TEXT NOT NULL, terms TEXT NOT NULL, price DECIMAL(10,2) NULL, badge VARCHAR(60) NOT NULL DEFAULT '', start_date DATE NULL, end_date DATE NULL, active TINYINT NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS package_services (package_id INT NOT NULL, service_id INT NOT NULL, PRIMARY KEY(package_id,service_id), FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE CASCADE, FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (id VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS quotes (id INT AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(40) NOT NULL UNIQUE, submission_key VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(190) NOT NULL DEFAULT '', city VARCHAR(120) NOT NULL, details TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Nueva', notes TEXT NOT NULL, consent_at DATETIME NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS quote_items (id INT AUTO_INCREMENT PRIMARY KEY, quote_id INT NOT NULL, item_type VARCHAR(15) NOT NULL, item_id INT NOT NULL, name VARCHAR(150) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NULL, FOREIGN KEY(quote_id) REFERENCES quotes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rate_limits (id VARCHAR(64) PRIMARY KEY, attempts INT NOT NULL, reset_at BIGINT NOT NULL) ENGINE=InnoDB;
